"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["44492"],{43483(e){e.exports=JSON.parse('{"id":"V4-006","slug":"debit-card","term":"Debit Card","also_known_as":[],"difficulty":"Beginner","definition":"A debit card is a payment card linked directly to a bank account, so that purchases and cash withdrawals are taken from the account\u2019s available balance, rather than being borrowed as with a credit card.","explanation":["Debit cards let people pay in shops, online and by contactless tap, and withdraw cash from cash machines, using their own money. Payments usually leave the account almost immediately or within a day or two.","Because spending is limited to the money in the account, debit cards help people avoid building up debt. If an account has an arranged overdraft, however, a debit card payment can take the balance below zero, which may incur fees or interest.","For example, a customer with 500 in their current account who buys groceries for 80 by debit card will see their balance fall to 420.","Debit cards differ from credit cards in several ways. Credit cards offer an interest-free period and may help build a credit history, while debit cards usually do not affect credit scores. Legal protections for credit card purchases can be stronger in some countries, although card networks offer chargeback schemes for both types. Debit card details should be protected carefully, since fraud takes money directly from the account."],"note":"","total":1725,"prev":{"slug":"debit","term":"Debit"},"next":{"slug":"debt","term":"Debt"}}')}}]);